import{_ as a,o as i,c as o,a2 as s}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Origen y Esencia de las Entidades Oscuras de Reemplazo","description":"","frontmatter":{},"headers":[],"relativePath":"es/57-黑暗置换体起源与本质.md","filePath":"es/57-黑暗置换体起源与本质.md"}'),n={name:"es/57-黑暗置换体起源与本质.md"};function r(d,e,l,t,c,m){return i(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="origen-y-esencia-de-las-entidades-oscuras-de-reemplazo" tabindex="-1">Origen y Esencia de las Entidades Oscuras de Reemplazo <a class="header-anchor" href="#origen-y-esencia-de-las-entidades-oscuras-de-reemplazo" aria-label="Permalink to &quot;Origen y Esencia de las Entidades Oscuras de Reemplazo&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>57</td></tr><tr><td>Módulo</td><td>Razas y Formas de Vida</td></tr><tr><td>Palabras clave</td><td>Entidad Oscura de Reemplazo, Energía Abisal, coexistencia de dos almas, origen y esencia, amenaza simbiótica</td></tr></tbody></table><h2 id="i-definicion-de-las-entidades-oscuras-de-reemplazo" tabindex="-1">I. Definición de las Entidades Oscuras de Reemplazo <a class="header-anchor" href="#i-definicion-de-las-entidades-oscuras-de-reemplazo" aria-label="Permalink to &quot;I. Definición de las Entidades Oscuras de Reemplazo&quot;">​</a></h2><p>En el Universo Original Wanling Hengmao (Universo Hengyuan), una &quot;Entidad Oscura de Reemplazo&quot; se refiere a una forma de vida especial formada después de que un ser vivo es erosionado por la Energía Abisal u otra energía oscura, donde el alma original es parcial o completamente reemplazada por la energía oscura, formando una forma de vida especial en la que coexisten el alma original y un alma oscura. Una Entidad Oscura de Reemplazo no es simplemente un &quot;ser vivo infectado por energía oscura&quot;, sino un ser que ha experimentado un reemplazo y reconstrucción a nivel del alma. Su esencia es que un solo cuerpo contiene dos almas mutuamente conflictivas y mutuamente dependientes: el alma anfitriona original y el alma de reemplazo oscura.</p><p>Las Entidades Oscuras de Reemplazo están entre los problemas más complejos de ética vital y gobernanza de seguridad que enfrenta la Civilización Simbiótica del Ancla. Se diferencian tanto de la vida anómala (la vida anómala es vida desconocida completamente nueva, mientras que las Entidades Oscuras de Reemplazo son el producto de vida conocida modificada) como de los seres infectados ordinariamente por energía (los seres infectados ordinarios solo tienen erosionado su cuerpo, mientras que las almas de las Entidades Oscuras de Reemplazo ya han sido reemplazadas). Su particularidad radica en que involucran el conflicto de derechos de dos almas, dilemas éticos y riesgos de seguridad, requiriendo reglas dedicadas de identificación, ética y tratamiento.</p><h2 id="ii-origen-de-las-entidades-oscuras-de-reemplazo" tabindex="-1">II. Origen de las Entidades Oscuras de Reemplazo <a class="header-anchor" href="#ii-origen-de-las-entidades-oscuras-de-reemplazo" aria-label="Permalink to &quot;II. Origen de las Entidades Oscuras de Reemplazo&quot;">​</a></h2><p>La generación de las Entidades Oscuras de Reemplazo requiere condiciones y procesos específicos. Su origen puede rastrearse hasta los siguientes aspectos:</p><h3 id="i-la-fuente-de-la-energia-abisal" tabindex="-1">(I) La Fuente de la Energía Abisal <a class="header-anchor" href="#i-la-fuente-de-la-energia-abisal" aria-label="Permalink to &quot;(I) La Fuente de la Energía Abisal&quot;">​</a></h3><p>La Energía Abisal es el factor central en la generación de las Entidades Oscuras de Reemplazo. La Energía Abisal proviene del Abismo Cósmico: la región más oscura en el nivel más bajo del Universo Hengyuan, donde se acumula la energía oscura primitiva rechazada en el nacimiento del universo. La Energía Abisal posee las siguientes características:</p><table tabindex="0"><thead><tr><th>Característica</th><th>Descripción</th></tr></thead><tbody><tr><td>Erosividad</td><td>La Energía Abisal puede erosionar el cuerpo y el alma de los seres vivos, transformándolos gradualmente en atributos oscuros</td></tr><tr><td>Tentación</td><td>La Energía Abisal puede amplificar las emociones negativas y los deseos de los seres vivos, induciéndolos a aceptar activamente la energía oscura</td></tr><tr><td>Reemplazo</td><td>Tras alcanzar cierta concentración, la Energía Abisal puede reemplazar el alma de un ser vivo, formando un alma de reemplazo oscura</td></tr><tr><td>Infectividad</td><td>Las Entidades Oscuras de Reemplazo pueden transmitir la Energía Abisal a otros seres vivos mediante contacto, ataques, intrusión de conciencia, etc.</td></tr><tr><td>Evolutividad</td><td>La Energía Abisal puede evolucionar junto con la evolución del huésped, produciendo habilidades oscuras más poderosas</td></tr></tbody></table><h3 id="ii-condiciones-de-generacion" tabindex="-1">(II) Condiciones de Generación <a class="header-anchor" href="#ii-condiciones-de-generacion" aria-label="Permalink to &quot;(II) Condiciones de Generación&quot;">​</a></h3><p>La generación de las Entidades Oscuras de Reemplazo requiere la satisfacción simultánea de las siguientes condiciones:</p><ol><li><strong>Exposición a la Energía Abisal</strong>: el ser vivo está expuesto a Energía Abisal de alta concentración, o tiene contacto prolongado con Energía Abisal de baja concentración.</li><li><strong>Período de vulnerabilidad del alma</strong>: el alma del ser vivo está en un estado vulnerable, como durante avances de cultivo, heridas graves, fluctuaciones emocionales extremas, colapsos mentales, etc.</li><li><strong>Catálisis de emociones negativas</strong>: el ser vivo alberga fuertes emociones negativas, como resentimiento, miedo, codicia, desesperación, etc.; estas emociones son los mejores catalizadores de la Energía Abisal.</li><li><strong>Aceptación activa o pasiva</strong>: el ser vivo acepta activamente el poder oscuro bajo la tentación de la Energía Abisal, o es erosionado pasivamente cuando es impotente para resistir.</li><li><strong>Completación del reemplazo del alma</strong>: la Energía Abisal echa raíces en el alma y completa el reemplazo, formando un alma de reemplazo oscura independiente.</li></ol><h3 id="iii-vias-de-generacion" tabindex="-1">(III) Vías de Generación <a class="header-anchor" href="#iii-vias-de-generacion" aria-label="Permalink to &quot;(III) Vías de Generación&quot;">​</a></h3><p>Las Entidades Oscuras de Reemplazo se generan principalmente a través de las siguientes vías:</p><ul><li><strong>Contacto con la región abisal</strong>: el ser vivo entra en el Abismo Cósmico o en una zona de fuga de Energía Abisal y es erosionado por Energía Abisal de alta concentración.</li><li><strong>Conversión de cultivador oscuro</strong>: el cultivador practica activamente artes oscuras, absorbiendo Energía Abisal durante un largo período, y finalmente es reemplazado por un alma oscura.</li><li><strong>Infección por Entidad Oscura de Reemplazo</strong>: ser atacado por una Entidad Oscura de Reemplazo existente o sometido a intrusión de conciencia, con la Energía Abisal invadiendo a través de heridas o canales de conciencia.</li><li><strong>Maldiciones de ruinas y reliquias</strong>: contactar ruinas antiguas u objetos malditos contaminados por Energía Abisal, siendo erosionado por la energía oscura sellada en ellos.</li><li><strong>Accidentes de experimentos</strong>: ocurren accidentes en experimentos que involucran Energía Abisal, y el personal experimental es erosionado por Energía Abisal fuera de control.</li><li><strong>Intrusión por fisuras transplanares</strong>: seres oscuros intrusos del Plano Abisal a través de fisuras transplanares reemplazan directamente las almas de los seres vivos locales.</li></ul><h2 id="iii-esencia-de-las-entidades-oscuras-de-reemplazo" tabindex="-1">III. Esencia de las Entidades Oscuras de Reemplazo <a class="header-anchor" href="#iii-esencia-de-las-entidades-oscuras-de-reemplazo" aria-label="Permalink to &quot;III. Esencia de las Entidades Oscuras de Reemplazo&quot;">​</a></h2><p>La esencia de una Entidad Oscura de Reemplazo es una &quot;entidad de coexistencia de dos almas&quot;, con las siguientes características centrales:</p><h3 id="i-estructura-de-dos-almas" tabindex="-1">(I) Estructura de dos almas <a class="header-anchor" href="#i-estructura-de-dos-almas" aria-label="Permalink to &quot;(I) Estructura de dos almas&quot;">​</a></h3><p>Hay dos almas independientes en el cuerpo de una Entidad Oscura de Reemplazo:</p><table tabindex="0"><thead><tr><th>Alma</th><th>Nombre</th><th>Características</th></tr></thead><tbody><tr><td>Alma anfitriona original</td><td>El alma que originalmente pertenecía al huésped</td><td>Conserva los recuerdos, la personalidad, la conciencia y las emociones del huésped original, pero su poder está suprimido por el alma oscura</td></tr><tr><td>Alma de reemplazo</td><td>El alma oscura formada por la condensación de la Energía Abisal</td><td>Tiene conciencia, recuerdos y personalidad independientes, con poder poderoso, inclinada hacia la oscuridad y la depredación</td></tr></tbody></table><p>Las dos almas comparten el mismo cuerpo y se disputan el control del cuerpo. En la mayoría de los casos, el alma de reemplazo oscura ocupa la posición dominante, y el alma anfitriona original está suprimida en lo más profundo de la conciencia; pero bajo condiciones específicas (como estimulación emocional intensa, purificación por energía de luz sagrada o erupción de la voluntad del huésped original), el alma anfitriona original puede recuperar temporalmente el control del cuerpo.</p><h3 id="ii-conflicto-e-interdependencia-de-las-almas" tabindex="-1">(II) Conflicto e interdependencia de las almas <a class="header-anchor" href="#ii-conflicto-e-interdependencia-de-las-almas" aria-label="Permalink to &quot;(II) Conflicto e interdependencia de las almas&quot;">​</a></h3><p>Existe una compleja relación de conflicto e interdependencia entre las dos almas:</p><ul><li><strong>Conflicto</strong>: las dos almas se disputan el control del cuerpo; el alma anfitriona original intenta expulsar el alma oscura para recuperar la libertad, mientras que el alma oscura intenta aniquilar completamente el alma anfitriona original y controlar totalmente el cuerpo.</li><li><strong>Interdependencia</strong>: las dos almas comparten el mismo cuerpo y origen de vida; la desaparición de una puede causar la desaparición de la otra o el colapso del cuerpo. El alma oscura necesita el alma anfitriona original como &quot;ancla&quot; para mantener su existencia en el mundo material, mientras que el alma anfitriona original necesita el poder del alma oscura para mantener el funcionamiento del cuerpo (en casos de reemplazo profundo).</li><li><strong>Posibilidad de fusión</strong>: en casos extremadamente raros, las dos almas pueden alcanzar la reconciliación y lograr la fusión de almas, formando un alma nueva que posee tanto los recuerdos del huésped original como el poder oscuro.</li></ul><h3 id="iii-caracteristicas-de-habilidades" tabindex="-1">(III) Características de habilidades <a class="header-anchor" href="#iii-caracteristicas-de-habilidades" aria-label="Permalink to &quot;(III) Características de habilidades&quot;">​</a></h3><p>Las Entidades Oscuras de Reemplazo generalmente poseen las siguientes características de habilidades:</p><ol><li><strong>Manipulación de energía oscura</strong>: pueden manipular la Energía Abisal y la energía de atributos oscuros, lanzando hechizos y ataques oscuros.</li><li><strong>Refuerzo corporal</strong>: el cuerpo es reforzado por la Energía Abisal, con fuerza, velocidad y poder defensivo muy superiores a los de los seres vivos ordinarios.</li><li><strong>Capacidad de regeneración</strong>: poseen poderosa capacidad de regeneración, con las heridas ordinarias recuperándose rápidamente.</li><li><strong>Capacidad de infección</strong>: pueden transmitir la Energía Abisal a otros seres vivos mediante ataques o contacto, creando nuevas Entidades Oscuras de Reemplazo.</li><li><strong>Percepción reforzada</strong>: poseen percepción extremadamente fuerte de la energía oscura, las emociones negativas y el aura vital.</li><li><strong>Transformación de forma</strong>: pueden transformarse en forma oscura o forma monstruosa, aumentando aún más el poder de combate.</li><li><strong>Ataque al alma</strong>: pueden atacar directamente las almas de otros seres vivos, causando trauma del alma o contaminación del alma.</li></ol><h3 id="iv-tendencias-de-comportamiento" tabindex="-1">(IV) Tendencias de comportamiento <a class="header-anchor" href="#iv-tendencias-de-comportamiento" aria-label="Permalink to &quot;(IV) Tendencias de comportamiento&quot;">​</a></h3><p>Las tendencias de comportamiento de una Entidad Oscura de Reemplazo dependen de qué alma ocupa la posición dominante:</p><ul><li><strong>Cuando domina el alma oscura</strong>: el comportamiento tiende a la destrucción, la depredación, el asesinato y la propagación de la energía oscura, con fuerte agresividad y tendencias antisociales.</li><li><strong>Cuando domina el alma anfitriona original</strong>: el comportamiento tiende a la personalidad y los valores originales del huésped, pero está influenciado por la energía oscura, con emociones más fácilmente fluctuantes y más fácilmente provocadas.</li><li><strong>Cuando las dos almas están en conflicto</strong>: el comportamiento se manifiesta como caos y contradicción, a veces lúcido y a veces fuera de control, representando un peligro tanto para sí mismo como para los demás.</li></ul><h2 id="iv-etapas-de-desarrollo-de-las-entidades-oscuras-de-reemplazo" tabindex="-1">IV. Etapas de Desarrollo de las Entidades Oscuras de Reemplazo <a class="header-anchor" href="#iv-etapas-de-desarrollo-de-las-entidades-oscuras-de-reemplazo" aria-label="Permalink to &quot;IV. Etapas de Desarrollo de las Entidades Oscuras de Reemplazo&quot;">​</a></h2><p>Desde la erosión hasta el reemplazo completo, una Entidad Oscura de Reemplazo generalmente atraviesa las siguientes etapas de desarrollo:</p><table tabindex="0"><thead><tr><th>Etapa</th><th>Nombre</th><th>Características</th><th>Reversibilidad</th></tr></thead><tbody><tr><td>Primera etapa</td><td>Período de erosión energética</td><td>La Energía Abisal comienza a erosionar el cuerpo, con malestar físico y fluctuaciones emocionales; el alma aún no ha sido reemplazada</td><td>Totalmente reversible</td></tr><tr><td>Segunda etapa</td><td>Período de contaminación del alma</td><td>La Energía Abisal invade el alma; el alma anfitriona original es contaminada, con cambios de personalidad e impulsos oscuros</td><td>Mayormente reversible</td></tr><tr><td>Tercera etapa</td><td>Período de formación de dos almas</td><td>Se forma el alma de reemplazo oscura, se establece la estructura de coexistencia de dos almas, y el alma anfitriona original comienza a ser suprimida</td><td>Parcialmente reversible</td></tr><tr><td>Cuarta etapa</td><td>Período de dominación oscura</td><td>El alma oscura ocupa completamente la posición dominante, el alma anfitriona original está profundamente suprimida, y el cuerpo está básicamente transformado por la energía oscura</td><td>Difícil de revertir</td></tr><tr><td>Quinta etapa</td><td>Período de reemplazo completo</td><td>El alma anfitriona original es completamente aniquilada o asimilada, el alma oscura controla totalmente el cuerpo, convirtiéndose en una existencia puramente oscura</td><td>Irreversible</td></tr></tbody></table><p>De la primera a la tercera etapa, las Entidades Oscuras de Reemplazo aún tienen posibilidad de recuperación; después de entrar en la cuarta etapa, la recuperación es extremadamente difícil; en la quinta etapa, el huésped original ya no existe y solo puede tratarse como una existencia puramente oscura.</p><h2 id="v-la-relacion-entre-las-entidades-oscuras-de-reemplazo-y-la-civilizacion-simbiotica" tabindex="-1">V. La Relación entre las Entidades Oscuras de Reemplazo y la Civilización Simbiótica <a class="header-anchor" href="#v-la-relacion-entre-las-entidades-oscuras-de-reemplazo-y-la-civilizacion-simbiotica" aria-label="Permalink to &quot;V. La Relación entre las Entidades Oscuras de Reemplazo y la Civilización Simbiótica&quot;">​</a></h2><p>Las Entidades Oscuras de Reemplazo son un gran desafío para la Civilización Simbiótica del Ancla. Su relación con la civilización simbiótica se refleja en los siguientes aspectos:</p><ol><li><strong>Conflicto conceptual</strong>: el alma oscura de una Entidad Oscura de Reemplazo tiende a la depredación y la destrucción, oponiéndose fundamentalmente al concepto de &quot;antipredacionismo, promoción de la simbiosis&quot; de la civilización simbiótica.</li><li><strong>Amenaza de seguridad</strong>: las Entidades Oscuras de Reemplazo poseen poderosas habilidades de combate e infección, representando una amenaza directa para la seguridad de la civilización simbiótica.</li><li><strong>Dilema ético</strong>: el alma anfitriona original dentro de una Entidad Oscura de Reemplazo es un miembro legítimo de la civilización simbiótica, y sus derechos básicos deben protegerse; sin embargo, el peligro del alma oscura exige medidas de control. Cómo equilibrar ambos es un profundo dilema ético.</li><li><strong>Desafío de gobernanza</strong>: la identificación, el aislamiento, el tratamiento y el manejo de las Entidades Oscuras de Reemplazo requieren instituciones y recursos dedicados, imponiendo altas exigencias a la capacidad de gobernanza de la civilización simbiótica.</li><li><strong>Posibilidad de transformación</strong>: mientras el alma anfitriona original aún exista, mediante purificación, fusión, separación y otros medios, algunas Entidades Oscuras de Reemplazo pueden salvarse y reintegrarse al sistema simbiótico.</li></ol><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>Las Entidades Oscuras de Reemplazo son existencias especiales producidas por el entrelazamiento de la Energía Abisal y las almas de los seres vivos. Su esencia es una unidad contradictoria de coexistencia de dos almas. Son tanto una amenaza de seguridad para la civilización simbiótica como una prueba de su profundidad ética y capacidad de gobernanza. Comprender el origen y la esencia de las Entidades Oscuras de Reemplazo es la premisa y el fundamento para formular las Directrices Éticas del Alma Dual (véase <em>58-双魂伦理准则</em>) y las reglas de manejo de las cuatro ramas (véase <em>59-黑暗置换体四类分支处置</em>).</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>58-双魂伦理准则 (Directrices Éticas del Alma Dual)</li><li>59-黑暗置换体四类分支处置 (Manejo de las Cuatro Ramas de las Entidades Oscuras de Reemplazo)</li><li>55-奇异能量分类与特性 (Clasificación y Características de la Energía Anómala)</li><li>53-奇特生命识别标准 (Estándares de Identificación de la Vida Anómala)</li></ul>',42)])])}const g=a(n,[["render",r]]);export{p as __pageData,g as default};
